	 * #define PORT_ECHO 2
	 * 
	 * void opcontrol() {
	 *   pros::adi::Ultrasonic sensor (PORT_PING, PORT_ECHO);
	 *   while (true) {
	 *     // Print the distance read by the ultrasonic
	 *     std::cout << "Distance: " << sensor.get_value();
	 *     pros::delay(10);
	 *   }
	 * }
	 * \endcode
	 */
	std::int32_t get_value() const;

	using Port::get_port;
};

