	 * \code
	 * #define LED_PORT 'a'
	 * #define LED_LENGTH 3
	 * 
	 * void opcontrol() {
	 *   pros::Led led (LED_PORT, LED_LENGTH);
	 *   while (true) {
	 * 	   // Set the first 3 pixels to red, green, and blue
