/**
 * \file pros/distance.hpp
 * \ingroup cpp-distance
 *
 * Contains prototypes for the V5 Distance Sensor-related functions.
 *
 * This file should not be modified by users, since it gets replaced whenever
 * a kernel upgrade occurs.
 *
 * \copyright (c) 2017-2023, Purdue University ACM SIGBots.
 *
 * This Source Code Form is subject to the terms of the Mozilla Public
 * License, v. 2.0. If a copy of the MPL was not distributed with this
 * file, You can obtain one at http://mozilla.org/MPL/2.0/.
 *
 * \defgroup cpp-distance VEX Distance Sensor C++ API
 */

#ifndef _PROS_DISTANCE_HPP_
#define _PROS_DISTANCE_HPP_

#include <cstdint>
#include <iostream>

#include "pros/device.hpp"
#include "pros/distance.h"

namespace pros {
inline namespace v5 {
/**
 * \ingroup cpp-distance
 */
class Distance : public Device {
	/**
	 * \addtogroup cpp-distance
	 *  @{
	 */
	public:
	/**
	 * Creates a Distance Sensor object for the given port.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as a Distance Sensor
	 *
	 * \param port
	 *        The V5 port number from 1-21
	 *
	 * \b Example
	 * \code
	 * #define DISTANCE_PORT 1
	 *
	 * void opcontrol() {
	 *   Distance distance(DISTANCE_PORT);
	 * }
	 * \endcode
	 */
	Distance(const std::uint8_t port);

	Distance(const Device& device) : Distance(device.get_port()){};
	/**
	 * Get the currently measured distance from the sensor in mm
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Distance Sensor
	 *
	 * \return The distance value or PROS_ERR if the operation failed, setting
	 * errno. Will return 9999 if the sensor can not detect an object.
	 *
	 * \b Example
	 * \code
	 * #define DISTANCE_PORT 1
	 *
	 * void opcontrol() {
	  Distance distance(DISTANCE_PORT);
	 *   while (true) {
	 *     printf("Distance confidence: %d\n", distance.get());
	 *     delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t get();

	/**
	 * Get the currently measured distance from the sensor in mm.
	 * \note This function is identical to get().
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Distance Sensor
	 *
	 * \return The distance value or PROS_ERR if the operation failed, setting
	 * errno. Will return 9999 if the sensor can not detect an object.
	 *
	 * \b Example
	 * \code
	 * #define DISTANCE_PORT 1
	 *
	 * void opcontrol() {
	  Distance distance(DISTANCE_PORT);
	 *   while (true) {
	 *     printf("Distance confidence: %d\n", distance.get_distance());
	 *     delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t get_distance();

	/**
	 * Gets all distance sensors.
	 *
	 * \return A vector of Distance sensor objects.
	 *
	 * \b Example
	 * \code
	 * void opcontrol() {
	 *   std::vector<Distance> distance_all = pros::Distance::get_all_devices();  // All distance sensors that are
	 * connected
	 * }
	 * \endcode
	 */
	static std::vector<Distance> get_all_devices();

	/**
	 * Get the confidence in the distance reading
	 *
	 * This is a value that has a range of 0 to 63. 63 means high confidence,
	 * lower values imply less confidence. Confidence is only available
	 * when distance is > 200mm.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Distance Sensor
	 *
	 * \return The confidence value or PROS_ERR if the operation failed, setting
	 * errno.
	 *
	 * \b Example
	 * \code
	 * #define DISTANCE_PORT 1
	 *
	 * void opcontrol() {
	  Distance distance(DISTANCE_PORT);
	 *   while (true) {
	 *     printf("Distance confidence: %d\n", distance.get_confidence());
	 *     delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t get_confidence();

	/**
	 * Get the current guess at relative object size
	 *
	 * This is a value that has a range of 0 to 400.
	 * A 18" x 30" grey card will return a value of approximately 75
	 * in typical room lighting.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Distance Sensor
	 *
	 * \return The size value or PROS_ERR if the operation failed, setting
	 * errno. Will return -1 if the sensor is not able to determine object size.
	 *
	 * \b Example
	 * \code
	 * #define DISTANCE_PORT 1
	 *
	 * void opcontrol() {
	  Distance distance(DISTANCE_PORT);
	 *   while (true) {
	 *     printf("Distance confidence: %d\n", distance.get_object_size());
	 *     delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t get_object_size();

	/**
	 * Get the object velocity in m/s
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Distance Sensor
	 *
	 * \return The velocity value or PROS_ERR if the operation failed, setting
	 * errno.
	 *
	 * \b Example
	 * \code
	 *
	 * void opcontrol() {
	 *	Distance distance(DISTANCE_PORT);
	 *   while (true) {
	 *     printf("Distance Object velocity: %f\n", distance.get_object_velocity());
	 *     delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual double get_object_velocity();

	/**
	 * This is the overload for the << operator for printing to streams
	 *
	 * Prints in format(this below is all in one line with no new line):
	 * Distance [port: (port number), distance: (distance), confidence: (confidence),
	 * object size: (object size), object velocity: (object velocity)]
	 */
	friend std::ostream& operator<<(std::ostream& os, pros::Distance& distance);

	private:
	///@}
};

namespace literals {
/**
 * Constructs a Distance sensor object from a literal ending in _dist via calling the constructor
 *
 * \return a pros::Distance for the corresponding port
 *
 * \b Example
 * \code
 * using namespace pros::literals;
 * void opcontrol() {
 *	pros::Distance dist = 2_dist; //Makes an dist object on port 2
 * }
 * \endcode
 */
const pros::Distance operator"" _dist(const unsigned long long int d);
}  // namespace literals
}  // namespace v5
}  // namespace pros

#endif

sdk/pros/gps.hpp:
/**
 * \file pros/gps.hpp
 * \ingroup cpp-gps
 *
 * Contains prototypes for functions related to the VEX GPS.
 *
 * This file should not be modified by users, since it gets replaced whenever
 * a kernel upgrade occurs.
 *
 * \copyright (c) 2017-2023, Purdue University ACM SIGBots.
 *
 * This Source Code Form is subject to the terms of the Mozilla Public
 * License, v. 2.0. If a copy of the MPL was not distributed with this
 * file, You can obtain one at http://mozilla.org/MPL/2.0/.
 *
 * \defgroup cpp-gps VEX GPS Sensor C API
 * \note For a pros-specific usage guide on the GPS, please check out our article [here.](@ref gps)
 */

#ifndef _PROS_GPS_HPP_
#define _PROS_GPS_HPP_

#include <stdbool.h>

#include <cstdint>
#include <iostream>

#include "pros/device.hpp"
#include "pros/gps.h"

namespace pros {
inline namespace v5 {
/**
 * \ingroup cpp-gps
 *  @{
 */
class Gps : public Device {
	/**
	 * \addtogroup cpp-gps
	 *  @{
	 */

	public:
	/**
	 * Creates a GPS object for the given port.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as a GPS
	 * EAGAIN - The sensor is still calibrating
	 *
	 * \param port
	 *        The V5 port number from 1-21
	 * \b Example:
	 * \code
	 * pros::Gps gps(1);
	 * \endcode
	 *
	 */
	Gps(const std::uint8_t port) : Device(port, DeviceType::gps){};

	Gps(const Device& device) : Gps(device.get_port()){};

	/**
	 * Creates a GPS object for the given port.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as a GPS
	 * EAGAIN - The sensor is still calibrating
	 *
	 * \param port
	 *        The V5 port number from 1-21
	 * \param xInitial
	 * 				 Cartesian 4-Quadrant X initial position (meters)
	 * \param yInitial
	 * 				 Cartesian 4-Quadrant Y initial position (meters)
	 * \param headingInitial
	 * 				 Initial heading (degrees)
	 *
	 * \b Example:
	 * \code
	 * pros::Gps gps(1, 1.30, 1.20, 90);
	 * \endcode
	 *
	 */
	explicit Gps(const std::uint8_t port, double xInitial, double yInitial, double headingInitial)
	    : Device(port, DeviceType::gps) {
		pros::c::gps_set_position(port, xInitial, yInitial, headingInitial);
	};

	/**
	 * Creates a GPS object for the given port.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as a GPS
	 * EAGAIN - The sensor is still calibrating
	 *
	 * \param port
	 *        The V5 port number from 1-21
	 * \param xOffset
	 * 				 Cartesian 4-Quadrant X offset from center of turning (meters)
	 * \param yOffset
	 * 				 Cartesian 4-Quadrant Y offset from center of turning (meters)
	 *
	 * \b Example:
	 * \code
	 * pros::Gps gps(1, 1.30, 1.20);
	 * \endcode
	 *
	 */
	explicit Gps(const std::uint8_t port, double xOffset, double yOffset) : Device(port, DeviceType::gps) {
		pros::c::gps_set_offset(port, xOffset, yOffset);
	};

	/**
	 * Creates a GPS object for the given port.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as a GPS
	 * EAGAIN - The sensor is still calibrating
	 *
	 * \param port
	 *        The V5 port number from 1-21
	 * \param xInitial
	 * 				 Initial 4-Quadrant X Position, with (0,0) being at the center of the field (meters)
	 * \param yInitial
	 * 				 Initial 4-Quadrant Y Position, with (0,0) being at the center of the field (meters)
	 * \param headingInitial
	 * 				 Initial Heading, with 0 being North, 90 being East, 180 being South, and 270 being West (degrees)
	 * \param xOffset
	 * 				 Cartesian 4-Quadrant X offset from center of turning (meters)
	 * \param yOffset
	 * 				 Cartesian 4-Quadrant Y offset from center of turning (meters)
	 *
	 * \b Example:
	 * \code
	 * pros::Gps gps(1, 1.30, 1.20, 180, 1.30, 1.20);
	 * \endcode
	 *
	 */
	explicit Gps(const std::uint8_t port, double xInitial, double yInitial, double headingInitial, double xOffset,
	             double yOffset)
	    : Device(port, DeviceType::gps) {
		pros::c::gps_initialize_full(port, xInitial, yInitial, headingInitial, xOffset, yOffset);
	};

	/**
	 * Set the GPS's offset relative to the center of turning in meters,
	 * as well as its initial position.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as a GPS
	 * EAGAIN - The sensor is still calibrating
	 *
	 * \param  xOffset
	 * 				 Cartesian 4-Quadrant X offset from center of turning (meters)
	 * \param  yOffset
	 * 				 Cartesian 4-Quadrant Y offset from center of turning (meters)
	 * \param  xInitial
	 * 				 Initial 4-Quadrant X Position, with (0,0) being at the center of the field (meters)
	 * \param  yInitial
	 * 				 Initial 4-Quadrant Y Position, with (0,0) being at the center of the field (meters)
	 * \param  headingInitial
	 *  			 Heading with 0 being north on the field, in degrees [0,360) going clockwise
	 * \return 1 if the operation was successful or PROS_ERR if the operation
	 * failed, setting errno.
	 *
	 * \b Example
	 * \code
	 * #define GPS_PORT 1
	 *
	 * void opcontrol() {
	 * 	Gps gps(GPS_PORT, 1.1, 1.2, 180, .4, .4);
	 *  // this is equivalent to the above line
	 *  gps.initialize_full(1.1, 1.2, 180, .4, .4);
	 *   while (true) {
	 *     delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t initialize_full(double xInitial, double yInitial, double headingInitial, double xOffset,
	                                     double yOffset) const;

	/**
	 * Set the GPS's offset relative to the center of turning in meters.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as a GPS
	 * EAGAIN - The sensor is still calibrating
	 *
	 * \param  xOffset
	 * 				 Cartesian 4-Quadrant X offset from center of turning (meters)
	 * \param  yOffset
	 * 				 Cartesian 4-Quadrant Y offset from center of turning (meters)
	 * \return 1 if the operation was successful or PROS_ERR if the operation
	 * failed, setting errno.
	 *
	 * \b Example
	 * \code
	 * #define GPS_PORT 1
	 *
	 * void opcontrol() {
	 * 	Gps gps(GPS_PORT, 1.1, 1.2, 180, .4, .4);
	 *  // this is equivalent to the above line
	 *  gps.set_offset(.4, .4);
	 *   while (true) {
	 *	 	delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t set_offset(double xOffset, double yOffset) const;

	/**

	 * Gets all GPS sensors.
	 *
	 * \return A vector of Gps sensor objects.
	 *
	 * \b Example
	 * \code
	 * void opcontrol() {
	 *   std::vector<Gps> gps_all = pros::Gps::get_all_devices();  // All GPS sensors that are connected
	 * }
	 * \endcode
	 */
	static std::vector<Gps> get_all_devices();

	/**
	 * Get the GPS's cartesian location relative to the center of turning/origin in meters.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as a GPS
	 * EAGAIN - The sensor is still calibrating
	 *
	 * \param  port
	 * 				 The V5 GPS port number from 1-21
	 * \return A struct (gps_position_s_t) containing the X and Y values if the operation
	 * failed, setting errno.
	 *
	 * \b Example
	 * \code
	 * #define GPS_PORT 1
	 *
	 * void opcontrol() {
	 *   gps_position_s_t pos;
	 * 	Gps gps(GPS_PORT);
	 *   while (true) {
	 *     pos = gps.get_offset();
	 *     screen_print(TEXT_MEDIUM, 1, "X Offset: %4d, Y Offset: %4d", pos.x, pos.y);
	 *     delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual pros::gps_position_s_t get_offset() const;

	/**
	 * Sets the robot's location relative to the center of the field in meters.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as a GPS
	 * EAGAIN - The sensor is still calibrating
	 *
	 * \param  xInitial
	 * 				 Initial 4-Quadrant X Position, with (0,0) being at the center of the field (meters)
	 * \param  yInitial
	 * 				 Initial 4-Quadrant Y Position, with (0,0) being at the center of the field (meters)
	 * \param  headingInitial
	 *  			 Heading with 0 being north on the field, in degrees [0,360) going clockwise
	 * \return 1 if the operation was successful or PROS_ERR if the operation
	 * failed, setting errno.
	 *
	 * \b Example
	 * \code
	 * #define GPS_PORT 1
	 *
	 * void opcontrol() {
	 * 	Gps gps(GPS_PORT);
	 *  gps.set_position(1.3, 1.4, 180);
	 *   while (true) {
	 *     printf("X: %f, Y: %f, Heading: %f\n", gps.get_position().x,
	 * 	   gps.get_position().y, gps.get_position().heading);
	 *     delay(20);
	 *   }
	 * }
	 * \endcode
	 */
