 *     delay(20);
 *   }
 * }
 * \endcode
 */
const pros::Gps operator""_gps(const unsigned long long int g);
}  // namespace literals

/// @brief
/// Alias for Gps is GPS for user convenience.
using GPS = Gps;

}  // namespace v5
}  // namespace pros

#endif

