/**
 * \file pros/optical.hpp
 * \ingroup cpp-optical
 *
 * Contains prototypes for functions related to the VEX Optical sensor.
 *
 * This file should not be modified by users, since it gets replaced whenever
 * a kernel upgrade occurs.
 *
 * \copyright (c) 2017-2023, Purdue University ACM SIGBots.
 *
 * This Source Code Form is subject to the terms of the Mozilla Public
 * License, v. 2.0. If a copy of the MPL was not distributed with this
 * file, You can obtain one at http://mozilla.org/MPL/2.0/.
 *
 * \defgroup cpp-optical VEX Optical Sensor C++ API
 */

#ifndef _PROS_OPTICAL_HPP_
#define _PROS_OPTICAL_HPP_

#include <stdbool.h>

#include <cstdint>
#include <iostream>

#include "pros/device.hpp"
#include "pros/optical.h"

namespace pros {
inline namespace v5 {
/**
 * \ingroup cpp-optical
 */
class Optical : public Device {
	/**
	 * \addtogroup cpp-optical
	 *  @{
	 */
	public:
	/**
	 * Creates an Optical Sensor object for the given port.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
	 *
	 * \param port
	 *        The V5 port number from 1-21
	 *
	 * \b Example:
	 * \code{.cpp}
	 * pros::Optical optical(1);
	 * \endcode
	 */
	Optical(const std::uint8_t port);

	Optical(const Device& device) : Optical(device.get_port()){};


	/**
	 * Gets all optical sensors.
	 * 
	 * \return A vector of Optical sensor objects.
	 *
	 * \b Example
 	 * \code
	 * void opcontrol() {
	 *   std::vector<Optical> optical_all = pros::Optical::get_all_devices();  // All optical sensors that are connected
	 * }
 	 * \endcode
	 */
	static std::vector<Optical> get_all_devices();

	/**
	 * Get the detected color hue
	 *
	 * This is not available if gestures are being detected. Hue has a
	 * range of 0 to 359.999
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
	 *
	 * \return hue value if the operation was successful or PROS_ERR_F if the operation
	 * failed, setting errno.
	 *
	 * \b Example:
	 * \code{.cpp}
	 * void opcontrol() {
	 * 		pros::Optical optical(1);
	 * 		std::cout << "Hue: " << optical.get_hue() << std::endl;
	 * }
	 * \endcode
	 */
	virtual double get_hue();

	/**
	 * Get the detected color saturation
	 *
	 * This is not available if gestures are being detected. Saturation has a
	 * range of 0 to 1.0
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
	 *
	 * \return saturation value if the operation was successful or PROS_ERR_F if
	 * the operation failed, setting errno.
	 *
	 * \b Example:
	 * \code{.cpp}
	 * void opcontrol() {
	 * 		pros::Optical optical(1);
	 * 		std::cout << "Saturation: " << optical.get_saturation() << std::endl;
	 * }
	 * \endcode
	 */
	virtual double get_saturation();

	/**
	 * Get the detected color brightness
	 *
	 * This is not available if gestures are being detected. Brightness has a
	 * range of 0 to 1.0
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
	 *
	 * \return brightness value if the operation was successful or PROS_ERR_F if
	 * the operation failed, setting errno.
	 *
	 * \b Example:
	 * \code{.cpp}
	 * void opcontrol() {
	 * 		pros::Optical optical(1);
	 * 		std::cout << "Brightness: " << optical.get_brightness() << std::endl;
	 * }
	 * \endcode
	 */
	virtual double get_brightness();

	/**
	 * Get the detected proximity value
	 *
	 * This is not available if gestures are being detected. proximity has
	 * a range of 0 to 255.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
	 *
	 * \return Proximity value if the operation was successful or PROS_ERR if
	 * the operation failed, setting errno.
	 *
	 * \b Example:
	 * \code{.cpp}
	 * void opcontrol() {
	 * 		pros::Optical optical(1);
	 * 		std::cout << "Proximity: " << optical.get_proximity() << std::endl;
	 * }
	 * \endcode
	 */
	virtual std::int32_t get_proximity();

	/**
	 * Set the pwm value of the White LED on the sensor
	 *
	 * value that ranges from 0 to 100
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
	 *
	 * \return The Error code encountered or PROS_SUCCESS.
	 *
	 * \b Example:
	 * \code{.cpp}
	 * void initialize() {
	 * 		pros::Optical optical(1);
	 * 		optical.set_led_pwm(100);
	 * }
	 * \endcode
	 */
	virtual std::int32_t set_led_pwm(uint8_t value);

	/**
	 * Get the pwm value of the White LED on the sensor
	 *
	 * value that ranges from 0 to 100
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
	 *
	 * \return LED pwm value if the operation was successful or PROS_ERR if
	 * the operation failed, setting errno.
	 *
	 * \b Example:
	 * \code{.cpp}
	 * void opcontrol() {
	 * 		pros::Optical optical(1);
	 *		optical.set_led_pwm(100);
	 * 		std::cout << "LED PWM: " << optical.get_led_pwm() << std::endl;
	 * }
	 * \endcode
	 */
	virtual std::int32_t get_led_pwm();

	/**
	 * Get the processed RGBC data from the sensor
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
	 *
	 * \return rgb value if the operation was successful or an optical_rgb_s_t
	 * with all fields set to PROS_ERR if the operation failed, setting errno.
	 *
	 * \b Example:
	 * \code{.cpp}
	 * void opcontrol() {
	 * 		pros::Optical optical(1);
	 * 		pros::c::optical_rgb_s_t rgb = optical.get_rgb();
	 * 		while(1) {
	 * 			std::cout << "Red: " << rgb.red << std::endl;
	 * 			std::cout << "Green: " << rgb.green << std::endl;
	 * 			std::cout << "Blue: " << rgb.blue << std::endl;
	 * 			std::cout << "Brightness: " << rgb.brightness << std::endl;
	 * 			pros::delay(20);
	 * 		}
	 * }
	 * \endcode
	 */
	virtual pros::c::optical_rgb_s_t get_rgb();

	/**
	 * Get the raw un-processed RGBC data from the sensor
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
	 *
	 * \return raw rgb value if the operation was successful or an optical_raw_s_t
	 * with all fields set to PROS_ERR if the operation failed, setting errno.
	 *
	 * \b Example:
	 * \code{.cpp}
	 * void opcontrol() {
	 * 		pros::Optical optical(1);
	 * 		pros::c::optical_raw_s_t raw = optical.get_raw();
	 * 		while (1) {
	 * 			std::cout << "Red: " << raw.red << std::endl;
	 * 			std::cout << "Green: " << raw.green << std::endl;
	 * 			std::cout << "Blue: " << raw.blue << std::endl;
	 * 			std::cout << "Clear: " << raw.clear << std::endl;
	 * 			pros::delay(20);
	 * 		}
	 * }
	 * \endcode
	 */
	virtual pros::c::optical_raw_s_t get_raw();

	/**
	 * Get the most recent gesture data from the sensor
	 *
	 * Gestures will be cleared after 500mS
	 *
	 * 
	 * 0 = no gesture,
	 * 1 = up (towards cable),
	 * 2 = down,
	 * 3 = right,
	 * 4 = left
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
	 *
	 * \return gesture value if the operation was successful or PROS_ERR if
	 * the operation failed, setting errno.
	 *
	 * \b Example:
	 * \code{.cpp}
	 * void opcontrol() {
	 * 		pros::Optical optical(1);
	 * 		while(1) {
	 * 			std::cout << "Gesture: " << optical.get_gesture() << std::endl;
	 * 			pros::delay(20);
	 * 		}
	 * }
	 * \endcode
	 */
	virtual pros::c::optical_direction_e_t get_gesture();

	/**
	 * Get the most recent raw gesture data from the sensor
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
	 *
	 * \return gesture value if the operation was successful or an optical_gesture_s_t
	 * with all fields set to PROS_ERR if the operation failed, setting errno.
	 *
	 * \b Example:
	 * \code{.cpp}
	 * void opcontrol() {
	 * 		pros::Optical optical(1);
	 *		optical.enable_gesture();
	 * 		while(1) {
	 * 			pros::c::optical_gesture_s_t gesture = optical.get_gesture_raw();
	 * 			std::cout << "Gesture raw data: " << std::endl;
	 * 			std::cout << "Up data: " << gesture.udata << std::endl;
	 * 			std::cout << "Down data: " << gesture.ddata << std::endl;
	 * 			std::cout << "Left data: " << gesture.ldata << std::endl;
	 * 			std::cout << "Right data: " << gesture.rdata << std::endl;
	 * 			std::cout << "Type: " << gesture.type << std::endl;
	 * 			std::cout << "Count: " << gesture.count << std::endl;
	 * 			std::cout << "Time: " << gesture.time << std::endl;
	 * 			pros::delay(20);
	 * 		}
	 * }
	 * \endcode
	 */
	virtual pros::c::optical_gesture_s_t get_gesture_raw();

	/**
	 * Enable gesture detection on the sensor
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
	 *
	 * \return 1 if the operation is successful or PROS_ERR if the operation failed,
	 * setting errno.
	 *
	 * \b Example:
	 * \code{.cpp}
	 * void opcontrol() {
	 * 		pros::Optical optical(1);
	 *		optical.enable_gesture();
	 * 		while(1) {
	 * 			pros::c::optical_gesture_s_t gesture = optical.get_gesture_raw();
	 * 			std::cout << "Gesture raw data: " << std::endl;
	 * 			std::cout << "Up data: " << gesture.udata << std::endl;
	 * 			std::cout << "Down data: " << gesture.ddata << std::endl;
	 * 			std::cout << "Left data: " << gesture.ldata << std::endl;
	 * 			std::cout << "Right data: " << gesture.rdata << std::endl;
	 * 			std::cout << "Type: " << gesture.type << std::endl;
	 * 			std::cout << "Count: " << gesture.count << std::endl;
	 * 			std::cout << "Time: " << gesture.time << std::endl;
	 * 			pros::delay(20);
	 * 		}
	 * }
	 * \endcode
	 */
	virtual std::int32_t enable_gesture();

	/**
	 * Disable gesture detection on the sensor
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
	 *
	 * \return 1 if the operation is successful or PROS_ERR if the operation failed,
	 * setting errno.
	 *
	 * \b Example:
	 * \code{.cpp}
	 * void opcontrol() {
	 * 		pros::Optical optical(1);
	 *		optical.enable_gesture();
	 * 		while(1) {
	 * 			if(optical.get_gesture() != 0) {
	 * 				std::cout << "Gesture detected!"<< std::endl;
	 * 				optical.disable_gesture();
	 * 			}
	 * 			pros::delay(20);
	 * 		}
	 * }
	 * \endcode
	 */
	virtual std::int32_t disable_gesture();

	/**
	 * Set integration time (update rate) of the optical sensor in milliseconds, with
	 * minimum time being 3 ms and maximum time being 712 ms. Default is 100 ms, with the 
	 * optical sensor communciating with the V5 brain every 20 ms. 
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
 	 *
	 * \return 1 if the operation is successful or PROS_ERR_F if the operation failed,
	 * setting errno.
	 */
	double get_integration_time();

	/**
	 * Get integration time (update rate) of the optical sensor in milliseconds.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Optical Sensor
	 *
	 * \param time
	 *        The desired integration time in milliseconds
	 * \return Integration time in milliseconds if the operation is successful 
	 *  or PROS_ERR if the operation failed, setting errno.
	 */
	std::int32_t set_integration_time(double time);

	/**
	 * This is the overload for the << operator for printing to streams
	 *
	 * Prints in format(this below is all in one line with no new line):
	 * Optical [port: (port number), hue: (hue), saturation: (saturation),
	 * brightness: (brightness), proximity: (proximity), rgb: {red, green, blue}]
	 *
	 * \b Example:
	 * \code{.cpp}
	 * pros::Optical optical(1);
	 * std::cout << optical << std::endl;
	 * \endcode
	 */
	friend std::ostream& operator<<(std::ostream& os, pros::Optical& optical);

	private:
	///@}
};

namespace literals {
/**
 * Constructs a Optical sensor from a literal ending in _opt
 *
 * \return a pros::Optical for the corresponding port
 *
 * \b Example
 * \code
 * using namespace pros::literals;
 * void opcontrol() {
 *	pros::Optical opt = 2_opt; //Makes an Optical object on port 2
 * }
 * \endcode
 */
const pros::Optical operator"" _opt(const unsigned long long int o);
}  // namespace literals
}  // namespace v5
}  // namespace pros

#endif

sdk/pros/rotation.hpp:
/**
 * \file pros/rotation.hpp
 * \ingroup cpp-rotation
 *
 * Contains prototypes for functions related to the VEX Rotation Sensor.
 *
 * This file should not be modified by users, since it gets replaced whenever
 * a kernel upgrade occurs.
 *
 * \copyright (c) 2017-2023, Purdue University ACM SIGBots.
 *
 * This Source Code Form is subject to the terms of the Mozilla Public
 * License, v. 2.0. If a copy of the MPL was not distributed with this
 * file, You can obtain one at http://mozilla.org/MPL/2.0/.
 *
 * \defgroup cpp-rotation VEX Rotation Sensor C++ API
 */
#ifndef _PROS_ROTATION_HPP_
#define _PROS_ROTATION_HPP_

#include <cstdint>
#include <iostream>

#include "pros/device.hpp"
#include "pros/rotation.h"

namespace pros {
inline namespace v5 {
/**
 * \ingroup cpp-rotation
 */
class Rotation : public Device {
	/**
	 * \addtogroup cpp-rotation
	 * @{
	 */

	public:
	/**
	 * Constructs a new Rotation Sensor object
	 *
	 * ENXIO - The given value is not within the range of V5 ports |1-21|.
	 * ENODEV - The port cannot be configured as a Rotation Sensor
	 *
	 * \param port
	 *        The V5 port number from 1 to 21, or from -21 to -1 for reversed Rotation Sensors.
	 *
	 * 	\b Example
	 * \code
	 * void opcontrol() {
	 * 	 pros::Rotation rotation_sensor(1); //Creates a Rotation Sensor on port 1
	 *   pros::Rotation reversed_rotation_sensor(-2); //Creates a reversed Rotation Sensor on port 2
	 * }
	 * \endcode
	 */
	Rotation(const std::int8_t port);

	Rotation(const Device& device) : Rotation(device.get_port()){};


	/**
	 * Reset the Rotation Sensor
	 *
	 * Reset the current absolute position to be the same as the
	 * Rotation Sensor angle.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Rotation Sensor
	 *
	 * \return 1 if the operation was successful or PROS_ERR if the operation
	 * failed, setting errno.
	 *
	 *  \b Example
	 * \code
	 * void opcontrol() {
	 *   pros::Rotation rotation_sensor(1);
	 *   pros::Controller master (E_CONTROLLER_MASTER);
	 *   while (true) {
	 *     if(master.get_analog(E_CONTROLLER_DIGITAL_X) {
	 * 	     rotation_sensor.reset();
	 *     }
	 *     pros::delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t reset();

	/**
	 * Set the Rotation Sensor's refresh interval in milliseconds.
	 *
	 * The rate may be specified in increments of 5ms, and will be rounded down to
	 * the nearest increment. The minimum allowable refresh rate is 5ms. The default
	 * rate is 10ms.
	 *
	 * As values are copied into the shared memory buffer only at 10ms intervals,
	 * setting this value to less than 10ms does not mean that you can poll the
	 * sensor's values any faster. However, it will guarantee that the data is as
	 * recent as possible.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Rotation Sensor
	 *
	 * \param rate The data refresh interval in milliseconds
	 * \return 1 if the operation was successful or PROS_ERR if the operation
	 * failed, setting errno.
	 *
	 *  \b Example
	 * \code
	 * void initialize() {
	 *   pros::Rotation rotation_sensor(1);
	 *   rotation_sensor.set_data_rate(5);
	 * }
	 * \endcode
	 */
	virtual std::int32_t set_data_rate(std::uint32_t rate) const;

	/**
	 * Set the Rotation Sensor position reading to a desired rotation value
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Rotation Sensor
	 *
	 * \param position
	 * 		  The position in terms of ticks
	 * \return 1 if the operation was successful or PROS_ERR if the operation
	 * failed, setting errno.
	 *
	 *  \b Example
	 * \code
	 * void opcontrol() {
	 *   pros::Rotation rotation_sensor(1);
	 *   pros::Controller master (E_CONTROLLER_MASTER);
	 *   while (true) {
	 *     if(master.get_analog(E_CONTROLLER_DIGITAL_X) {
	 * 	     rotation_sensor.set_position(600);
	 *     }
	 *     pros::delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t set_position(std::uint32_t position) const;

	/**
	 * Reset the Rotation Sensor position to 0
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Rotation Sensor
	 *
	 * \param position
	 * 		  The position in terms of ticks
	 * \return 1 if the operation was successful or PROS_ERR if the operation
	 * failed, setting errno.
	 *
	 * \b Example
	 * \code
	 * void opcontrol() {
	 *   pros::Rotation rotation_sensor(1);
	 *   pros::Controller master (E_CONTROLLER_MASTER);
	 *   while (true) {
	 *     if(master.get_analog(E_CONTROLLER_DIGITAL_X) {
	 * 	     rotation_sensor.reset_position();
	 *     }
	 *     pros::delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t reset_position(void) const;

	/**
	 * Gets all rotation sensors.
	 * 
	 * \return A vector of Rotation sensor objects.
	 *
	 * \b Example
 	 * \code
	 * void opcontrol() {
	 *   std::vector<Rotation> rotation_all = pros::Rotation::get_all_devices();  // All rotation sensors that are connected
	 * }
 	 * \endcode
	 */
	static std::vector<Rotation> get_all_devices();

	/**
	 * Get the Rotation Sensor's current position in centidegrees
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Rotation Sensor
	 *
	 * \return The position value or PROS_ERR if the operation failed, setting
	 * errno.
	 *
	 *  \b Example
	 * \code
	 * void opcontrol() {
	 * 	 pros::Rotation rotation_sensor(1);
	 *   while (true) {
	 *     printf("Position: %d Ticks \n", rotation_sensor.get_position());
	 *     delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t get_position() const;

	/**
	 * Get the Rotation Sensor's current velocity in centidegrees per second
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Rotation Sensor
	 *
	 * \param  port
	 * 				 The V5 Rotation Sensor port number from 1-21
	 * \return The velocity value or PROS_ERR if the operation failed, setting
	 * errno.
	 *
	 *  \b Example
	 * \code
	 * void opcontrol() {
	 * 	 pros::Rotation rotation_sensor(1);
	 *   while (true) {
	 *     printf("Velocity: %d centidegrees per second \n", rotation_sensor.get_velocity));
	 *     delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t get_velocity() const;

	/**
	 * Get the Rotation Sensor's current position in centidegrees
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Rotation Sensor
	 *
	 * \return The angle value or PROS_ERR if the operation failed, setting
	 * errno.
	 *
	 *  \b Example
	 * \code
	 * void opcontrol() {
	 * 	 pros::Rotation rotation_sensor(1);
	 *   while (true) {
	 *     printf("Angle: %d centidegrees \n", rotation_sensor.get_angle());
	 *     delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t get_angle() const;

	/**
	 * Set the Rotation Sensor's direction reversed flag
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Rotation Sensor
	 *
	 * \param  value
	 * 				 Determines if the direction of the rotational sensor is
	 * 				 reversed or not.
	 *
	 * \return 1 if the operation was successful or PROS_ERR if the operation
	 * failed, setting errno.
	 *
	 *  \b Example
	 * \code
	 * void opcontrol() {
	 *   pros::Rotation rotation_sensor(1);
	 *   pros::Controller master (E_CONTROLLER_MASTER);
	 *   while (true) {
	 *     if(master.get_analog(E_CONTROLLER_DIGITAL_X) {
	 * 	     rotation_sensor.set_reversed(true); // Reverses the Rotation Sensor
	 *     }
	 *     pros::delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t set_reversed(bool value) const;

	/**
	 * Reverse the Rotation Sensor's direction.
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Rotation Sensor
	 *
	 * \return 1 if the operation was successful or PROS_ERR if the operation
	 * failed, setting errno.
	 *
	 *  \b Example
	 * \code
	 * void opcontrol() {
	 *   pros::Rotation rotation_sensor(1);
	 *   pros::Controller master (E_CONTROLLER_MASTER);
	 *   while (true) {
	 *     if(master.get_analog(E_CONTROLLER_DIGITAL_X) {
	 * 	     rotation_sensor.reverse();
	 *     }
	 *     pros::delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t reverse() const;

	/**
	 * Get the Rotation Sensor's reversed flag
	 *
	 * This function uses the following values of errno when an error state is
	 * reached:
	 * ENXIO - The given value is not within the range of V5 ports (1-21).
	 * ENODEV - The port cannot be configured as an Rotation Sensor
	 *
	 * \return Reversed value or PROS_ERR if the operation failed, setting
	 * errno.
	 *
	 *  \b Example
	 * \code
	 * void opcontrol() {
	 * 	 pros::Rotation rotation_sensor(1);
	 *   while (true) {
	 *     printf("Reversed: %d \n", rotation_sensor.get_reversed());
	 *     delay(20);
	 *   }
	 * }
	 * \endcode
	 */
	virtual std::int32_t get_reversed() const;

	/**
	 * This is the overload for the << operator for printing to streams
	 *
	 * Prints in format(this below is all in one line with no new line):
	 * Rotation [port: rotation._port, position: (rotation position), velocity: (rotation velocity),
	 * angle: (rotation angle), reversed: (reversed boolean)]
	 *
	 * \b Example
	 * \code
	 * #define ROTATION_PORT 1
	 *
	 * void opcontrol() {
	 * 	pros::Rotation rotation_sensor(1);
	 *  while(true) {
	 *		std::cout << rotation_sensor << std::endl;
	 *  	pros::delay(20);
	 *  }
	 * }
	 * \endcode
	 */
	friend std::ostream& operator<<(std::ostream& os, const pros::Rotation& rotation);

	///@}
};

namespace literals {
/**
 * Constructs a Rotation sensor from a literal ending in _rot
 *
 * \return a pros::Rotation for the corresponding port
 *
 * \b Example
 * \code
 * using namespace pros::literals;
 * void opcontrol() {
 *	pros::Rotation rotation = 2_rot; //Makes an Motor object on port 2
 * }
 * \endcode
 */
const pros::Rotation operator"" _rot(const unsigned long long int r);
}  // namespace literals
}  // namespace v5
}  // namespace pros

#endif

sdk/pros/screen.hpp:
/**
 * \file screen.hpp
 * \ingroup cpp-screen
 *
 * Brain screen display and touch functions.
 *
 * Contains user calls to the v5 screen for touching and displaying graphics.
 *
 * \copyright (c) 2017-2023, Purdue University ACM SIGBots.
 *
 * This Source Code Form is subject to the terms of the Mozilla Public
 * License, v. 2.0. If a copy of the MPL was not distributed with this
 * file, You can obtain one at http://mozilla.org/MPL/2.0/.
 * 
 * \defgroup cpp-screen Simplified Brain Screen C++ API
 */

#ifndef _PROS_SCREEN_HPP_
#define _PROS_SCREEN_HPP_

#include "pros/screen.h"
#include "pros/colors.hpp"
#include <cstdint>
#include <string>

namespace pros {
namespace screen {

#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wunused-function"

namespace {
template <typename T>
T convert_args(T arg) {
	return arg;
}
const char* convert_args(const std::string& arg) {
	return arg.c_str();
}
}  // namespace

#pragma GCC diagnostic pop

/**
 * \ingroup cpp-screen
 */

/**
 * \addtogroup cpp-screen
 *  @{
 */

    /******************************************************************************/
    /**                  Screen Graphical Display Functions                      **/
    /**                                                                          **/
    /**   These functions allow programmers to display shapes on the v5 screen   **/
    /******************************************************************************/

    /**
     * Set the pen color for subsequent graphics operations
     * 
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param color	The pen color to set (it is recommended to use values
     * 		 from the enum defined in colors.hpp)
     * 
     * \return Returns 1 if the mutex was successfully returned, or PROS_ERR if 
     * there was an error either taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void initialize() {
     *   pros::screen::set_pen(red);
     * }
     * 
     * void opcontrol() {
     * int iter = 0;
     *  while(1){
     *   // This should print in red.
     *   pros::screen::print(TEXT_MEDIUM, 1, "%d", iter++);
     *  }
     * }
     *
     * \endcode
     */
    std::uint32_t set_pen(pros::Color color);

    /**
     * Set the pen color for subsequent graphics operations
     * 
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param color	The pen color to set (in hex form)
     * 
     * \return Returns 1 if the mutex was successfully returned, or PROS_ERR if 
     * there was an error either taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void initialize() {
     *   //set pen color to red
     *   pros::screen::set_pen(0x00FF0000);
     * }
     * 
     * void opcontrol() {
     * int iter = 0;
     *  while(1){
     *   // This should print in red.
     *   pros::screen::print(TEXT_MEDIUM, 1, "%d", iter++);
     *  }
     * }
     *
     * \endcode
     */
    std::uint32_t set_pen(std::uint32_t color);

    /**
     * Set the eraser color for erasing and the current background.
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     * 
     * \param color	The background color to set (it is recommended to use values
     * 					from the enum defined in colors.hpp)
     * 
     * \return Returns 1 if the mutex was successfully returned, or PROS_ERR
     *  if there was an error either taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void initialize() {
     *   //set eraser color to red
     *   set_eraser(red);
     * }
     * 
     * void opcontrol() {
     * int iter = 0;
     *  while(1){
     *   // This should print in red.
     *   pros::screen::print(TEXT_MEDIUM, 1, "%d", iter++);
     *  }
     * }
     *
     * \endcode
     */
    std::uint32_t set_eraser(pros::Color color);

    /**
     * Set the eraser color for erasing and the current background.
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     * 
     * \param color	The background color to set to set (in hex form)
     * 
     * \return Returns 1 if the mutex was successfully returned, or PROS_ERR
     *  if there was an error either taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void initialize() {
     *   //set eraser color to red
     *   pros::screen::set_eraser(0x00FF0000);
     * }
     * 
     * void opcontrol() {
     *   while(1){
     *   // This should turn the screen red.
     *   pros::screen::erase();
     *   }
     * }
     * \endcode
     */
    std::uint32_t set_eraser(std::uint32_t color);

    /**
     *  Get the current pen color.
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     * 
     * \return The current pen color in the form of a value from the enum 
     * defined in colors.h, or PROS_ERR if there was an error taking or 
     * returning the screen mutex.
     * 
     * \b Example
     * \code
     * void initialize() {
     *   pros::screen::set_pen(red);
     * }
     *
     * void opcontrol() {
     *   while(1){
     *     // Should print number equivalent to red defined in colors.hpp.
     *     pros::screen::print(TEXT_MEDIUM, 1, "%d", get_pen());
     *   }
     * }
     * \endcode
     */
    std::uint32_t get_pen();

    /**
     * Get the current eraser color.
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \return The current eraser color in the form of a value from the enum
     *  defined in colors.h, or PROS_ERR if there was an error taking or 
     *  returning the screen mutex.
     * 
     * \b Example
     * \code
     * void initialize() {
     *   pros::screen::set_eraser(red);
     * }
     *
     * void opcontrol() {
     *   while(1){
     *     // Should print number equivalent to red defined in colors.h.
     *     pros::screen::print(TEXT_MEDIUM, 1, "%d", get_eraser());
     *   }
     * }
     * \endcode
     */
    std::uint32_t get_eraser();

    /**
     * Clear display with eraser color
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured 
     *         taking or returning the screen mutex.
     * 
     *  * \b Example
     * \code
     * void initialize() {
     *   pros::screen::set_eraser(red);
     * }
     *
     * void opcontrol() {
     *   while(1){
     *     // This should turn the screen red.
     *     pros::screen::erase();
     *   }
     * }
     * \endcode
     */
    std::uint32_t erase();

    /**
     * Scroll lines on the display upwards.
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param start_line    The line from which scrolling will start
     * \param lines			The number of lines to scroll up
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured
     *  taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void opcontrol() {
     *   pros::screen::print(TEXT_MEDIUM, 4, "Line Here");
     *   // Scroll 3 lines
     *   pros::screen::scroll(4, 3);
     * }
     * \endcode
     */
    std::uint32_t scroll(const std::int16_t start_line, const std::int16_t lines);

    /**
     * Scroll lines within a region on the display
     *
     * This function behaves in the same way as `screen_scroll`, except that you
     * specify a rectangular region within which to scroll lines instead of a start
     * line.
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param x0, y0	The (x,y) coordinates of the first corner of the
     * 						rectangular region
     * \param x1, y1	The (x,y) coordinates of the second corner of the
     * 						rectangular region
     * \param lines 	The number of lines to scroll upwards
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured 
     * taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void opcontrol() {
     *   pros::screen::print(TEXT_MEDIUM, 1, "Line Here");
     *   // Scrolls area of screen upwards slightly. including line of text
     *   pros::screen::scroll_area(0,0, 400, 200, 3);
     * }
     * \endcode
     */
    std::uint32_t scroll_area(const std::int16_t x0, const std::int16_t y0, const std::int16_t x1, const std::int16_t y1, std::int16_t lines);

    /**
     * Copy a screen region (designated by a rectangle) from an off-screen buffer 
     * to the screen
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param x0, y0 	The (x,y) coordinates of the first corner of the
     * 						rectangular region of the screen
     * \param x1, y1	The (x,y) coordinates of the second corner of the
     * 						rectangular region of the screen
     * \param buf		Off-screen buffer containing screen data
     * \param stride	Off-screen buffer width in pixels, such that image size
     * 						is stride-padding
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured taking
     *  or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void opcontrol() {
     *   uint32_t* buf = malloc(sizeof(uint32_t) * 400 * 200);
     *   pros::screen::print(TEXT_MEDIUM, 1, "Line Here");
     *   // Copies area of the screen including text
     *   pros::screen::copy_area(0, 0, 400, 200, (uint32_t*)buf, 400 + 1);
     *   // Equation for stride is x2 - x1 + 1
     * }
     * \endcode
     */
    std::uint32_t copy_area(const std::int16_t x0, const std::int16_t y0, const std::int16_t x1, const std::int16_t y1, uint32_t* buf, const std::int32_t stride);

    /**
     * Draw a single pixel on the screen using the current pen color
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param x, y 	The (x,y) coordinates of the pixel
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured 
     * taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * int i = 0;
     * void opcontrol() {
     *   while(i < 200){
     *     pros::screen::draw_pixel(100,i++);
     *     // Draws a line at x = 100 gradually down the screen, pixel by pixel
     *     pros::delay(200);
     *   }
     * }
     * \endcode
     */
    std::uint32_t draw_pixel(const std::int16_t x, const std::int16_t y);

    /**
     * Erase a pixel from the screen (Sets the location)
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param x, y 	The (x,y) coordinates of the erased
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured 
     * taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void opcontrol() {
     *   // Color the Screen in Red
     *   pros::screen::set_pen(red);
     *   pros::screen::fill_rect(0,0,400,200);
     *   int i = 0;
     *   while(i < 200){
     *     pros::screen::erase_pixel(100,i++);
     *     // Erases a line at x = 100 gradually down the screen, pixel by pixel
     *     pros::delay(200);
     *   }
     * }
     * \endcode
     */
    std::uint32_t erase_pixel(const std::int16_t x, const std::int16_t y);

    /**
     * Draw a line on the screen using the current pen color
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param x0, y0	The (x, y) coordinates of the first point of the line
     * \param x1, y1 	The (x, y) coordinates of the second point of the line
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured 
     * taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void opcontrol() {
     * 	 pros::screen::set_pen(red);
     *   // Draw line down the screen at x = 100
     *   pros::screen::draw_line(100,0,100,200);
     * }
     * \endcode
     */
    std::uint32_t draw_line(const std::int16_t x0, const std::int16_t y0, const std::int16_t x1, const std::int16_t y1);

    /**
     * Erase a line on the screen using the current eraser color
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param x0, y0	The (x, y) coordinates of the first point of the line
     * \param x1, y1 	The (x, y) coordinates of the second point of the line
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured 
     * taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void opcontrol() {
     *   // Color the Screen in Red
     *   pros::screen::set_pen(red);
     *   pros::screen::fill_rect(0,0,400,200);
     *   // Erase line down the screen at x = 100
     *   pros::screen::erase_line(100,0,100,200);
     * }
     * \endcode
     */
    std::uint32_t erase_line(const std::int16_t x0, const std::int16_t y0, const std::int16_t x1, const std::int16_t y1);

    /**
     * Draw a rectangle on the screen using the current pen color
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param x0, y0 	The (x,y) coordinates of the first point of the rectangle
     * \param x1, y1 	The (x,y) coordinates of the second point of the rectangle
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured 
     * taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void opcontrol() {
     *   pros::screen::set_pen(red);
     *   pros::screen::draw_rect(1,1,480,200);
     * }
     * \endcode
     */
    std::uint32_t draw_rect(const std::int16_t x0, const std::int16_t y0, const std::int16_t x1, const std::int16_t y1);

    /**
     * Erase a rectangle on the screen using the current eraser color
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param x0, y0 	The (x,y) coordinates of the first point of the rectangle
     * \param x1, y1 	The (x,y) coordinates of the second point of the rectangle
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured 
     * taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void opcontrol() {
     *   // Draw Box Around Half the Screen in Red
     *   pros::screen::set_eraser(red);
     *   pros::screen::erase_rect(5,5,240,200);
     * }
     * \endcode
     */
    std::uint32_t erase_rect(const std::int16_t x0, const std::int16_t y0, const std::int16_t x1, const std::int16_t y1);

    /**
     * Fill a rectangular region of the screen using the current pen
     * 		  color
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param x0, y0 	The (x,y) coordinates of the first point of the rectangle
     * \param x1, y1 	The (x,y) coordinates of the second point of the rectangle
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured 
     * taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void opcontrol() {
     *   // Fill Around Half the Screen in Red
     *   pros::screen::set_pen(red);
     *   pros::screen::fill_rect(5,5,240,200);
     * }
     * \endcode
     */
    std::uint32_t fill_rect(const std::int16_t x0, const std::int16_t y0, const std::int16_t x1, const std::int16_t y1);

    /**
     * Draw a circle on the screen using the current pen color
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param x, y 	The (x,y) coordinates of the center of the circle
     * \param r 	The radius of the circle
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured 
     * taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void opcontrol() {
     *   // Draw a circle with radius of 100 in red
     *   pros::screen::set_pen(red);
     *   pros::screen::draw_circle(240, 200, 100);
     * }
     * \endcode
     */
    std::uint32_t draw_circle(const std::int16_t x, const std::int16_t y, const std::int16_t radius);

    /**
     * Erase a circle on the screen using the current eraser color
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param x, y 	The (x,y) coordinates of the center of the circle
     * \param r 	The radius of the circle
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured 
     * taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * void opcontrol() {
     *   pros::screen::set_pen(red);
     *   pros::screen::fill_rect(5,5,240,200);
     *   // Erase a circle with radius of 100 in blue
     *   pros::screen::set_pen(blue);
     *   pros::screen::erase_circle(240, 200, 100);
     * }
     * \endcode
     */
    std::uint32_t erase_circle(const std::int16_t x, const std::int16_t y, const std::int16_t radius);

    /**
     * Fill a circular region of the screen using the current pen
     * 		  color
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     *
     * \param x, y 	The (x,y) coordinates of the center of the circle
     * \param r 	The radius of the circle
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured 
     * taking or returning the screen mutex.
     * 
     * \b Example
     * \code
    * void opcontrol() {
     *   pros::screen::set_pen(red);
     *   pros::screen::fill_rect(5,5,240,200);
     *   // Fill a circlular area with radius of 100 in blue
     *   pros::screen::set_pen(blue);
     *   pros::screen::fill_circle(240, 200, 100);
     * }
     * \endcode
     */
    std::uint32_t fill_circle(const std::int16_t x, const std::int16_t y, const std::int16_t radius);

    /******************************************************************************/
    /**                       Screen Text Display Functions                      **/
    /**                                                                          **/
    /**     These functions allow programmers to display text on the v5 screen   **/
    /******************************************************************************/

    /**
     * Print a formatted string to the screen, overwrite available for printing at location too.
     * 
     * Will default to a medium sized font by default if invalid txt_fmt is given.
     * 
     * \param txt_fmt Text format enum that determines if the text is medium, large, medium_center, or large_center. (DOES NOT SUPPORT SMALL)
     * \param line The line number on which to print
     * \param x The (x,y) coordinates of the top left corner of the string
     * \param y The (x,y) coordinates of the top left corner of the string
     * \param fmt  Format string
     * \param ...  Optional list of arguments for the format string
     * 
     * \b Example
     * \code
     * void opcontrol() {
     *    int i = 0;
     *    pros::screen::set_pen(blue);
     *    while(1){
     *       // Will print seconds started since program started on line 3
     *       pros::screen::print(pros::TEXT_MEDIUM, 3, "Seconds Passed: %3d", i++);
     *       pros::delay(1000);
     *    }
     * }
     */
    template <typename... Params>
    void print(pros::text_format_e_t txt_fmt, const std::int16_t line, const char* text, Params... args){
	    pros::c::screen_print(txt_fmt, line, text, convert_args(args)...);
    }

    template <typename... Params>
    void print(pros::text_format_e_t txt_fmt, const std::int16_t x, const std::int16_t y, const char* text, Params... args){
	    pros::c::screen_print_at(txt_fmt, x, y, text, convert_args(args)...);
    }

    /******************************************************************************/
    /**                         Screen Touch Functions                           **/
    /**                                                                          **/
    /**               These functions allow programmers to access                **/
    /**                    information about screen touches                      **/
    /******************************************************************************/

   /**
     * Gets the touch status of the last touch of the screen.
     * 
     * \return The last_touch_e_t enum specifier that indicates the last touch status of the screen (E_TOUCH_EVENT_RELEASE, E_TOUCH_EVENT_PRESS, or E_TOUCH_EVENT_PRESS_AND_HOLD).
     * This will be released by default if no action was taken. 
     * If an error occured, the screen_touch_status_s_t will have its 
     * last_touch_e_t enum specifier set to E_TOUCH_ERR, and other values set to -1.
     * 
     * \b Example
     * \code
     * void opcontrol() {
     *   int i = 0;
     *   pros::screen_touch_status_s_t status;
     *   while(1){
     *     status = pros::touch_status();
     *
     *     // Will print various information about the last touch
     *     pros::screen::print(TEXT_MEDIUM, 1, "Touch Status (Type): %d", status.touch_status);
     *     pros::screen::print(TEXT_MEDIUM, 2, "Last X: %d", status.x);
     *     pros::screen::print(TEXT_MEDIUM, 3, "Last Y: %d", status.y);
     *     pros::screen::print(TEXT_MEDIUM, 4, "Press Count: %d", status.press_count);
     *     pros::screen::print(TEXT_MEDIUM, 5, "Release Count: %d", status.release_count);
     *     pros::delay(20);
     *   }
     * }
     * \endcode
     */
    screen_touch_status_s_t touch_status();

    /**
     * Assigns a callback function to be called when a certain touch event happens.
     *
     * This function uses the following values of errno when an error state is
     * reached:
     * EACCESS - Another resource is currently trying to access the screen mutex.
     * 
     * \param cb Function pointer to callback when event type happens
     * \param event_type Touch event that will trigger the callback.
     * 
     * \return 1 if there were no errors, or PROS_ERR if an error occured 
     * while taking or returning the screen mutex.
     * 
     * \b Example
     * \code
     * touch_event_cb_fn_t changePixel(){
     *   pros::screen_touch_status_s_t status = pros::screen::touch_status();
     *   pros::screen::draw_pixel(status.x,status.y);
     *   return NULL;
     * }
     *
     * void opcontrol() {
     *   pros::screen::touch_callback(changePixel(), TOUCH_PRESSED);
     *   while(1) {
     *     pros::delay(20);
     *   }
     * }
     * \endcode
     */
    std::uint32_t touch_callback(touch_event_cb_fn_t cb, last_touch_e_t event_type);

} // namespace screen


} // namespace pros

extern __attribute__((weak)) void lvgl_init() {}
///@}
#endif //header guard

sdk/liblvgl/misc/lv_math.h:
/**
 * @file lv_math.h
 *
 */

#ifndef LV_MATH_H
#define LV_MATH_H

#ifdef __cplusplus
extern "C" {
#endif

/*********************
 *      INCLUDES
 *********************/
#include "liblvgl/lv_conf_internal.h"
#include <stdint.h>

/*********************
 *      DEFINES
 *********************/
#define LV_TRIGO_SIN_MAX 32767
#define LV_TRIGO_SHIFT 15 /**<  >> LV_TRIGO_SHIFT to normalize*/

#define LV_BEZIER_VAL_MAX 1024 /**< Max time in Bezier functions (not [0..1] to use integers)*/
#define LV_BEZIER_VAL_SHIFT 10 /**< log2(LV_BEZIER_VAL_MAX): used to normalize up scaled values*/

/**********************
 *      TYPEDEFS
 **********************/

typedef struct {
    uint16_t i;
    uint16_t f;
} lv_sqrt_res_t;

/**********************
 * GLOBAL PROTOTYPES
 **********************/

//! @cond Doxygen_Suppress
/**
 * Return with sinus of an angle
 * @param angle
 * @return sinus of 'angle'. sin(-90) = -32767, sin(90) = 32767
 */
LV_ATTRIBUTE_FAST_MEM int16_t lv_trigo_sin(int16_t angle);

static inline LV_ATTRIBUTE_FAST_MEM int16_t lv_trigo_cos(int16_t angle)
{
    return lv_trigo_sin(angle + 90);
}

//! @endcond

/**
 * Calculate a value of a Cubic Bezier function.
 * @param t time in range of [0..LV_BEZIER_VAL_MAX]
 * @param u0 start values in range of [0..LV_BEZIER_VAL_MAX]
 * @param u1 control value 1 values in range of [0..LV_BEZIER_VAL_MAX]
 * @param u2 control value 2 in range of [0..LV_BEZIER_VAL_MAX]
 * @param u3 end values in range of [0..LV_BEZIER_VAL_MAX]
 * @return the value calculated from the given parameters in range of [0..LV_BEZIER_VAL_MAX]
 */
uint32_t lv_bezier3(uint32_t t, uint32_t u0, uint32_t u1, uint32_t u2, uint32_t u3);

/**
 * Calculate the atan2 of a vector.
 * @param x
 * @param y
 * @return the angle in degree calculated from the given parameters in range of [0..360]
 */
uint16_t lv_atan2(int x, int y);

//! @cond Doxygen_Suppress

/**
 * Get the square root of a number
 * @param x integer which square root should be calculated
 * @param q store the result here. q->i: integer part, q->f: fractional part in 1/256 unit
 * @param mask optional to skip some iterations if the magnitude of the root is known.
 * Set to 0x8000 by default.
 * If root < 16: mask = 0x80
 * If root < 256: mask = 0x800
 * Else: mask = 0x8000
 */
LV_ATTRIBUTE_FAST_MEM void lv_sqrt(uint32_t x, lv_sqrt_res_t * q, uint32_t mask);

//! @endcond

/**
 * Calculate the integer exponents.
 * @param base
 * @param power
 * @return base raised to the power exponent
 */
int64_t lv_pow(int64_t base, int8_t exp);

/**
 * Get the mapped of a number given an input and output range
 * @param x integer which mapped value should be calculated
 * @param min_in min input range
 * @param max_in max input range
 * @param min_out max output range
 * @param max_out max output range
 * @return the mapped number
 */
int32_t lv_map(int32_t x, int32_t min_in, int32_t max_in, int32_t min_out, int32_t max_out);

/**
 * Get a pseudo random number in the given range
 * @param min   the minimum value
 * @param max   the maximum value
 * @return return the random number. min <= return_value <= max
 */
uint32_t lv_rand(uint32_t min, uint32_t max);

/**********************
 *      MACROS
 **********************/
#define LV_MIN(a, b) ((a) < (b) ? (a) : (b))
#define LV_MIN3(a, b, c) (LV_MIN(LV_MIN(a,b), c))
#define LV_MIN4(a, b, c, d) (LV_MIN(LV_MIN(a,b), LV_MIN(c,d)))

#define LV_MAX(a, b) ((a) > (b) ? (a) : (b))
#define LV_MAX3(a, b, c) (LV_MAX(LV_MAX(a,b), c))
#define LV_MAX4(a, b, c, d) (LV_MAX(LV_MAX(a,b), LV_MAX(c,d)))

#define LV_CLAMP(min, val, max) (LV_MAX(min, (LV_MIN(val, max))))

#define LV_ABS(x) ((x) > 0 ? (x) : (-(x)))
#define LV_UDIV255(x) (((x) * 0x8081U) >> 0x17)

#define LV_IS_SIGNED(t) (((t)(-1)) < ((t)0))
#define LV_UMAX_OF(t) (((0x1ULL << ((sizeof(t) * 8ULL) - 1ULL)) - 1ULL) | (0xFULL << ((sizeof(t) * 8ULL) - 4ULL)))
#define LV_SMAX_OF(t) (((0x1ULL << ((sizeof(t) * 8ULL) - 1ULL)) - 1ULL) | (0x7ULL << ((sizeof(t) * 8ULL) - 4ULL)))
#define LV_MAX_OF(t) ((unsigned long)(LV_IS_SIGNED(t) ? LV_SMAX_OF(t) : LV_UMAX_OF(t)))

#ifdef __cplusplus
} /*extern "C"*/
#endif

#endif

sdk/liblvgl/misc/lv_area.h:
/**
 * @file lv_area.h
 *
 */

#ifndef LV_AREA_H
#define LV_AREA_H

#ifdef __cplusplus
extern "C" {
#endif

/*********************
 *      INCLUDES
 *********************/
#include "liblvgl/lv_conf_internal.h"
#include <stdbool.h>
#include <stdint.h>

/*********************
 *      DEFINES
 *********************/

#if LV_USE_LARGE_COORD
typedef int32_t lv_coord_t;
#else
typedef int16_t lv_coord_t;
#endif

/**********************
 *      TYPEDEFS
 **********************/

/**
 * Represents a point on the screen.
 */
typedef struct {
    lv_coord_t x;
    lv_coord_t y;
} lv_point_t;

/** Represents an area of the screen.*/
typedef struct {
    lv_coord_t x1;
    lv_coord_t y1;
    lv_coord_t x2;
    lv_coord_t y2;
} lv_area_t;

/** Alignments*/
enum {
    LV_ALIGN_DEFAULT = 0,
    LV_ALIGN_TOP_LEFT,
    LV_ALIGN_TOP_MID,
    LV_ALIGN_TOP_RIGHT,
    LV_ALIGN_BOTTOM_LEFT,
    LV_ALIGN_BOTTOM_MID,
    LV_ALIGN_BOTTOM_RIGHT,
    LV_ALIGN_LEFT_MID,
    LV_ALIGN_RIGHT_MID,
    LV_ALIGN_CENTER,

    LV_ALIGN_OUT_TOP_LEFT,
    LV_ALIGN_OUT_TOP_MID,
    LV_ALIGN_OUT_TOP_RIGHT,
    LV_ALIGN_OUT_BOTTOM_LEFT,
    LV_ALIGN_OUT_BOTTOM_MID,
    LV_ALIGN_OUT_BOTTOM_RIGHT,
    LV_ALIGN_OUT_LEFT_TOP,
    LV_ALIGN_OUT_LEFT_MID,
    LV_ALIGN_OUT_LEFT_BOTTOM,
    LV_ALIGN_OUT_RIGHT_TOP,
    LV_ALIGN_OUT_RIGHT_MID,
    LV_ALIGN_OUT_RIGHT_BOTTOM,
};
typedef uint8_t lv_align_t;

enum {
    LV_DIR_NONE     = 0x00,
    LV_DIR_LEFT     = (1 << 0),
    LV_DIR_RIGHT    = (1 << 1),
    LV_DIR_TOP      = (1 << 2),
    LV_DIR_BOTTOM   = (1 << 3),
    LV_DIR_HOR      = LV_DIR_LEFT | LV_DIR_RIGHT,
    LV_DIR_VER      = LV_DIR_TOP | LV_DIR_BOTTOM,
    LV_DIR_ALL      = LV_DIR_HOR | LV_DIR_VER,
};

typedef uint8_t lv_dir_t;

/**********************
 * GLOBAL PROTOTYPES
 **********************/

/**
 * Initialize an area
 * @param area_p pointer to an area
 * @param x1 left coordinate of the area
 * @param y1 top coordinate of the area
 * @param x2 right coordinate of the area
 * @param y2 bottom coordinate of the area
 */
void lv_area_set(lv_area_t * area_p, lv_coord_t x1, lv_coord_t y1, lv_coord_t x2, lv_coord_t y2);

/**
 * Copy an area
 * @param dest pointer to the destination area
 * @param src pointer to the source area
 */
inline static void lv_area_copy(lv_area_t * dest, const lv_area_t * src)
{
    dest->x1 = src->x1;
    dest->y1 = src->y1;
    dest->x2 = src->x2;
    dest->y2 = src->y2;
}

/**
 * Get the width of an area
 * @param area_p pointer to an area
 * @return the width of the area (if x1 == x2 -> width = 1)
 */
static inline lv_coord_t lv_area_get_width(const lv_area_t * area_p)
{
    return (lv_coord_t)(area_p->x2 - area_p->x1 + 1);
}

/**
 * Get the height of an area
 * @param area_p pointer to an area
 * @return the height of the area (if y1 == y2 -> height = 1)
 */
static inline lv_coord_t lv_area_get_height(const lv_area_t * area_p)
{
    return (lv_coord_t)(area_p->y2 - area_p->y1 + 1);
}

/**
 * Set the width of an area
 * @param area_p pointer to an area
 * @param w the new width of the area (w == 1 makes x1 == x2)
 */
void lv_area_set_width(lv_area_t * area_p, lv_coord_t w);

/**
 * Set the height of an area
 * @param area_p pointer to an area
 * @param h the new height of the area (h == 1 makes y1 == y2)
 */
void lv_area_set_height(lv_area_t * area_p, lv_coord_t h);

/**
 * Set the position of an area (width and height will be kept)
